// Repository interface
interface IUserRepository {
  getUser(id: string): Promise<User>;
  saveUser(user: User): Promise<void>;
  deleteUser(id: string): Promise<void>;
}

// Repository implementasyonu
class UserRepository implements IUserRepository {
  constructor(private dataSource: UserDataSource) {}

  async getUser(id: string): Promise<User> {
    return await this.dataSource.getUser(id);
  }

  async saveUser(user: User): Promise<void> {
    await this.dataSource.saveUser(user);
  }

  async deleteUser(id: string): Promise<void> {
    await this.dataSource.deleteUser(id);
  }
}

// Oyun durumları
type GameState = 
  | 'loading'
  | 'menu'
  | 'playing'
  | 'paused'
  | 'gameover'
  | 'victory';

// State machine
class GameStateMachine {
  private state: GameState = 'loading';

  transition(newState: GameState): boolean {
    const validTransitions: Record<GameState, GameState[]> = {
      loading: ['menu'],
      menu: ['playing', 'loading'],
      playing: ['paused', 'gameover', 'victory'],
      paused: ['playing', 'menu'],
      gameover: ['menu'],
      victory: ['menu'],
    };

    if (validTransitions[this.state].includes(newState)) {
      this.state = newState;
      return true;
    }
    return false;
  }

  getState(): GameState {
    return this.state;
  }
}

