interface RenderPropsProps<T> {
  data: T[];
  render: (item: T, index: number) => ReactNode;
}

const RenderProps = <T,>({ data, render }: RenderPropsProps<T>) => (
  <FlatList
    data={data}
    renderItem={({ item, index }) => render(item, index)}
    keyExtractor={(item, index) => index.toString()}
  />
);

interface ToggleProps {
  isOn: boolean;
  onToggle: (isOn: boolean) => void;
}

const Toggle = ({ isOn, onToggle }: ToggleProps) => (
  <TouchableOpacity
    style={[styles.toggle, isOn && styles.toggleOn]}
    onPress={() => onToggle(!isOn)}
  />
);

// HOC
function withLoading<P extends object>(
  Component: React.ComponentType<P>
) {
  return (props: P & { loading: boolean }) => {
    if (props.loading) {
      return <ActivityIndicator />;
    }
    return <Component {...props} />;
  };
}

// Kullanım
const UserList = withLoading(({ users }: { users: User[] }) => (
  <FlatList
    data={users}
    renderItem={({ item }) => <UserItem user={item} />}
  />
));

import { useWindowDimensions } from 'react-native';

const ResponsiveContainer = ({ children }: { children: ReactNode }) => {
  const { width, height } = useWindowDimensions();
  const isTablet = width >= 768;
  const isDesktop = width >= 1024;

  return (
    <View style={[
      styles.container,
      isTablet && styles.tabletContainer,
      isDesktop && styles.desktopContainer
    ]}>
      {children}
    </View>
  );
};

import { SafeAreaView, useSafeAreaInsets } from 'react-native-safe-area-context';

const SafeScreen = ({ children }: { children: ReactNode }) => {
  const insets = useSafeAreaInsets();

  return (
    <SafeAreaView style={styles.container} edges={['top', 'bottom']}>
      <View style={{ paddingBottom: insets.bottom }}>
        {children}
      </View>
    </SafeAreaView>
  );
};

interface GridProps {
  children: ReactNode;
  columns?: number;
  gap?: number;
}

const Grid = ({ 
  children, 
  columns = 2, 
  gap = 12 
}: GridProps) => {
  const { width } = useWindowDimensions();

  // Responsive columns
  const responsiveColumns = useMemo(() => {
    if (width >= 1024) return 4;
    if (width >= 768) return 3;
    return columns;
  }, [width, columns]);

  return (
    <View style={[
      styles.grid,
      { gap }
    ]}>
      {React.Children.map(children, child => (
        <View style={{ flex: 1 / responsiveColumns }}>
          {child}
        </View>
      ))}
    </View>
  );
};

// Context
interface GameContextType {
  gameState: GameState;
  updateGameState: (state: GameState) => void;
}

const GameContext = createContext<GameContextType | undefined>(undefined);

// Provider
const GameProvider = ({ children }: { children: ReactNode }) => {
  const [gameState, setGameState] = useState<GameState>('menu');

  const updateGameState = useCallback((state: GameState) => {
    setGameState(state);
  }, []);

  const value = useMemo(() => ({
    gameState,
    updateGameState
  }), [gameState, updateGameState]);

  return (
    <GameContext.Provider value={value}>
      {children}
    </GameContext.Provider>
  );
};

// Custom hook
const useGame = () => {
  const context = useContext(GameContext);
  if (!context) {
    throw new Error('useGame must be used within GameProvider');
  }
  return context;
};

// Action types
type Action =
  | { type: 'SET_STATS'; payload: Stats }
  | { type: 'UPDATE_STAT'; payload: { key: string; value: number } }
  | { type: 'RESET_GAME' };

// Reducer
const gameReducer = (state: GameState, action: Action): GameState => {
  switch (action.type) {
    case 'SET_STATS':
      return { ...state, stats: action.payload };
    case 'UPDATE_STAT':
      return {
        ...state,
        stats: {
          ...state.stats,
          [action.payload.key]: action.payload.value
        }
      };
    case 'RESET_GAME':
      return initialState;
    default:
      return state;
  }
};

// Kullanım
const [state, dispatch] = useReducer(gameReducer, initialState);

const useMediaQuery = (minWidth: number) => {
  const { width } = useWindowDimensions();
  return width >= minWidth;
};

// Kullanım
const isTablet = useMediaQuery(768);

const useTheme = () => {
  const isDark = useColorScheme() === 'dark';

  return useMemo(() => ({
    colors: {
      background: isDark ? '#1a1a1a' : '#ffffff',
      text: isDark ? '#ffffff' : '#1a1a1a',
      primary: '#6366f1',
    },
    isDark,
  }), [isDark]);
};

const useLocalStorage = <T>(key: string, initialValue: T) => {
  const [storedValue, setStoredValue] = useState<T>(() => {
    try {
      const item = AsyncStorage.getItem(key);
      return item ? JSON.parse(item) : initialValue;
    } catch (error) {
      return initialValue;
    }
  });

  const setValue = useCallback(async (value: T) => {
    try {
      setStoredValue(value);
      await AsyncStorage.setItem(key, JSON.stringify(value));
    } catch (error) {
      console.error(error);
    }
  }, [key]);

  return [storedValue, setValue] as const;
};

// Fabric Component (TurboModule)
import { TurboModuleRegistry } from 'react-native';

export interface Spec extends TurboModule {
  getConstants(): { initialCount: number };
  increment(count: number): Promise<number>;
}

export default TurboModuleRegistry.getEnforcing<Spec>('YazgTurboModule');

// useTransition ile non-blocking UI
const SearchComponent = () => {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<SearchResult[]>([]);
  const [isPending, startTransition] = useTransition();

  const handleSearch = (text: string) => {
    setQuery(text);
    startTransition(() => {
      // Düşük öncelikli güncelleme
      setResults(searchData(text));
    });
  };

  return (
    <View>
      <TextInput value={query} onChangeText={handleSearch} />
      {isPending ? <ActivityIndicator /> : <ResultList results={results} />}
    </View>
  );
};

const useGameLoop = (tickRate: number = 60) => {
  const [isRunning, setIsRunning] = useState(false);
  const lastTickRef = useRef<number>(0);

  const gameLoop = useCallback((timestamp: number) => {
    if (!isRunning) return;

    const elapsed = timestamp - lastTickRef.current;
    const tickInterval = 1000 / tickRate;

    if (elapsed >= tickInterval) {
      // Game tick logic
      lastTickRef.current = timestamp;
    }

    requestAnimationFrame(gameLoop);
  }, [isRunning, tickRate]);

  const start = useCallback(() => {
    setIsRunning(true);
    lastTickRef.current = performance.now();
    requestAnimationFrame(gameLoop);
  }, [gameLoop]);

  const stop = useCallback(() => {
    setIsRunning(false);
  }, []);

  return { isRunning, start, stop };
};

type EventHandler<T = any> = (data: T) => void;

class EventBus {
  private listeners: Map<string, Set<EventHandler>> = new Map();

  on(event: string, handler: EventHandler): () => void {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, new Set());
    }
    this.listeners.get(event)!.add(handler);

    // Unsubscribe fonksiyonu döndür
    return () => this.off(event, handler);
  }

  off(event: string, handler: EventHandler): void {
    this.listeners.get(event)?.delete(handler);
  }

  emit(event: string, data?: any): void {
    this.listeners.get(event)?.forEach(handler => handler(data));
  }
}

// Kullanım
const eventBus = new EventBus();

// Event dinle
const unsubscribe = eventBus.on('game:over', (data) => {
  console.log('Game over!', data);
});

// Event tetikle
eventBus.emit('game:over', { score: 100 });

// Event dinlemeyi bırak
unsubscribe();
